"""Reads the nightly export."""
import pandas as pd

from . import config


def read_ratings(cfg):
    path = config.data_dir(cfg) / "ratings.csv.gz"
    df = pd.read_csv(path, parse_dates=["rated_at"], dtype={"rating_id": str})
    return df.sort_values("rating_id").reset_index(drop=True)


def read_members(cfg):
    return pd.read_csv(config.data_dir(cfg) / "members.csv")


def read_films(cfg):
    return pd.read_csv(config.data_dir(cfg) / "films.csv")
=== validate ===
"""Sanity checks run before the scores are published."""


class ValidationError(Exception):
    pass


def check(scores):
    if len(scores) == 0:
        raise ValidationError("no rows were scored")
    if scores["engagement"].isna().any():
        raise ValidationError("engagement contains nulls")
    bad = scores[(scores["engagement"] < 0.0) | (scores["engagement"] > 1.0)]
    if len(bad) > 0:
        raise ValidationError("engagement outside [0, 1] on %d rows" % len(bad))
    return True
